<template>
  <div class="shell" @touchstart="touchStart" @touchmove="touchMove" @touchend="touchEnd" @click="handlePanelDrilldown">
    <header class="topbar"><div><strong>{{ pageTitle }}</strong><span class="store">{{ auth.user?.store_name || auth.user?.storeName || '默认门店' }}</span><span class="gold">足金 ¥{{ money(app.primaryGold?.price) }}/g</span></div><div class="top-actions"><span class="online-dot" :class="{offline: app.offline}"></span><span>{{ app.offline ? '离线' : '在线' }}</span><button v-if="auth.can('goods:search')" class="icon-btn" @click="router.push('/goods/search')" aria-label="搜索货品">🔍</button><button v-if="auth.can('notification:view')" class="icon-btn" @click="section='notifications'" aria-label="消息">{{ app.unread ? `通知 ${app.unread}` : '通知' }}</button></div></header>
    <div class="mobile-silver-prices"><span>银卖价 <b>¥{{ money(app.silverSale?.price) }}/g</b></span><span>银回收价 <b>¥{{ money(app.silverRecycle?.price) }}/g</b></span></div>
    <div class="content"><section v-if="isManager && section === 'dashboard'" class="page"><div class="hero"><div><span>今日营业额</span><b>¥{{ money(dashboard?.amount) }}</b></div><div class="hero-side"><small>{{ todayLabel }}</small><small>足金卖价 ¥{{ money(app.primaryGold?.price) }}/g</small><small v-if="spotPrice" class="gold">行情参考 ¥{{ money(spotPrice) }}/g</small><small>{{ app.offline ? '离线模式' : (app.wsConnected ? '在线 · 实时连接正常' : '在线 · 实时连接重连中') }}</small></div></div><button v-if="app.pendingInboundCount" class="pending-inbound-entry" @click="router.push('/inbound/history')"><span><b>{{ app.pendingInboundCount }}</b> 条待同步入库单</span><em>联网后请逐单确认同步 ›</em></button><div class="kpi-grid kpi-tappable"><Kpi label="订单数" :value="dashboard?.order_count ?? 0" @click="openKpiDetail('orders')"/><Kpi label="销售克重" :value="`${dashboard?.weight ?? 0}g`" @click="openKpiDetail('weight')"/><Kpi label="回收克重" :value="`${dashboard?.recycle_weight ?? 0}g`" @click="openKpiDetail('recycle')"/><Kpi label="客单价" :value="`¥${money(dashboard?.avg_order)}`" @click="openKpiDetail('avg')"/></div><div class="quick-row"><button class="notice-card" @click="section='approval'"><b>{{ app.approvals.length }}</b><span>待审批</span><em>进入审批中心 ›</em></button><button class="notice-card" @click="section='goods'"><b>{{ warnings.length }}</b><span>库存预警</span><em>查看货品 ›</em></button><button class="notice-card" @click="router.push('/shift')"><b>⇄</b><span>交班结算</span><em>班次对账 ›</em></button></div><Panel title="其他功能"><div class="function-grid"><button v-for="item in managerFunctions" :key="item.key" v-permission="item.permission" class="function-entry" @click="openFunction(item)"><b>{{ FUNCTION_ICONS[item.key] || '▣' }}</b><span>{{ item.label }}</span></button></div></Panel><Panel title="员工排行榜"><div v-for="(row,i) in ranking" :key="i" class="rank-row"><span class="rank-no">{{ i+1 }}</span><span>{{ row.real_name || row.name || '员工' }}</span><strong>¥{{ money(row.amount || row.sales_amount) }}</strong><small>提成 ¥{{ money(row.commission) }}</small></div></Panel></section>
      <section v-else-if="isManager && section === 'approval'" class="page"><PageTitle title="审批中心"/><div class="seg"><button :class="{active: approvalView==='pending'}" @click="approvalView='pending'">待审批（{{ approvals.length }}）</button><button :class="{active: approvalView==='history'}" @click="openApprovalHistory">历史</button></div><template v-if="approvalView==='pending'"><div class="chips"><button v-for="t in approvalTabs" :key="t" :class="{active: approvalFilter===t}" @click="approvalFilter=t">{{ t }}</button></div><div v-if="!filteredApprovals.length" class="empty">暂无待审批</div><article v-for="item in filteredApprovals" :key="item.approval_id || item.id" class="panel approval-card" @click="openApprovalDetail(item)"><h3>{{ typeName(item.type) }}<span class="more">{{ (item.create_time || item.time || '').slice(5,16).replace('T',' ') }}</span></h3><p>{{ formatApprovalReason(item) }}</p><div class="approval-foot"><b>{{ Number(item.amount) ? '¥'+money(item.amount) : '—' }}</b><div class="card-actions"><button class="success" @click.stop="openApprovalDetail(item)">通过</button><button class="danger" @click.stop="openApprovalDetail(item,true)">驳回</button></div></div></article></template><template v-else><div v-if="!approvalHistoryData.length" class="empty">暂无审批历史</div><article v-for="item in approvalHistoryData" :key="'h'+item.approval_id" class="panel approval-card" @click="openApprovalDetail(item)"><h3>{{ typeName(item.type) }}<span class="more">{{ (item.approve_time||item.create_time||'').slice(5,16).replace('T',' ') }}</span></h3><p>{{ item.approve_remark || formatApprovalReason(item) }}</p><div class="approval-foot"><b :class="item.status===3?'ok':(item.status===4?'error':'')">{{ item.status===3?'已通过':(item.status===4?'已驳回':'已处理') }}</b></div></article></template><p class="fine">审批支持移动处理：通过 / 驳回（驳回必填原因），全程留痕</p></section>
      <section v-else-if="isManager && section === 'report'" class="page"><PageTitle title="业绩报表"><select v-model="period" @change="loadReport"><option value="daily">日</option><option value="weekly">周</option><option value="monthly">月</option></select></PageTitle><div class="kpi-grid"><Kpi label="营业额" :value="`¥${money(report?.amount)}`"/><Kpi label="毛利" :value="`¥${money(report?.gross_profit)}`"/><Kpi label="客单价" :value="`¥${money(report?.avg_order)}`"/><Kpi label="回收量" :value="`${report?.recycle_weight || 0}g`"/></div><p v-if="reportError" class="muted small">{{ reportError }}</p><Panel title="员工明细"><div v-for="(row,i) in commission" :key="i" class="rank-row"><span>{{ row.employee_name || row.real_name || '员工' }}</span><strong>¥{{ money(row.sales_amount || row.amount) }}</strong><small>{{ row.order_count || 0 }} 单 · 提成 ¥{{ money(row.commission_amount) }}</small></div></Panel><Panel :title="reportTabTitle"><div class="chips"><button v-for="t in reportTabs" :key="t.key" :class="{active: reportTab===t.key}" @click="reportTab=t.key">{{ t.label }}</button></div><template v-if="reportTab==='category'"><CategoryPie :rows="categoryRows"/></template><template v-else-if="reportTab==='pay'"><CategoryPie :rows="payMethodRows"/><div v-if="!payMethodRows.length" class="empty">今日暂无收款</div></template><template v-else><div class="kpi-grid"><Kpi label="回收单数" :value="recycleData.order_count||0"/><Kpi label="回收克重" :value="`${recycleData.weight||0}g`"/><Kpi label="回收金额" :value="`¥${money(recycleData.amount)}`"/><Kpi label="折旧损耗" :value="`¥${money(recycleData.deduct_loss)}`"/></div></template></Panel></section>
      <section v-else-if="isManager && section === 'member'" class="page"><PageTitle title="会员总览"><button v-if="auth.can('member:create')" class="outline" @click="memberCreateOpen=true">新增会员</button></PageTitle><div class="kpi-grid"><Kpi label="会员总数" :value="memberStats.total"/><Kpi label="新增会员" :value="memberStats.new"/><Kpi label="活跃会员" :value="memberStats.active"/><Kpi label="储值余额" :value="`¥${money(memberStats.balance)}`"/></div><Panel title="会员分层分析"><div v-for="t in tiers" :key="t.label" class="tier-row"><i class="tier-dot" :style="{background:t.color}"></i><span>{{ t.label }}</span><b>{{ t.count }} 人</b><small>累计消费 ¥{{ money(t.amount) }}</small></div><p class="muted small">按累计消费分层，基于最近500名会员</p></Panel><Panel :title="`本月生日会员（${birthdayMembers.length}）`"><div v-for="m in birthdayMembers.slice(0,10)" :key="'bm'+(m.member_id||m.id)" class="rank-row"><span>{{ m.name }}</span><small>生日 {{ (m.birthday||'').slice(5) }} · {{ maskPhone(m.phone) }}</small><button class="outline" @click="call(m.phone)">拨号</button></div><div v-if="!birthdayMembers.length" class="empty">本月暂无生日会员</div></Panel><MemberList :members="members" @open="openMember"/></section>
      <section v-else-if="!isManager && section === 'home'" class="page"><div class="hero"><div><span>{{ role === 'SALES' ? '本月个人销售' : '今日工作台' }}</span><b>{{ role === 'SALES' ? `¥${money(performance.amount)}` : (auth.user?.real_name || auth.user?.realName || auth.user?.username) }}</b></div><div class="hero-side"><small>{{ role === 'SALES' ? monthLabel : todayLabel }}</small><small>足金卖价 ¥{{ money(app.primaryGold?.price) }}/g</small><small>{{ app.offline ? '离线模式' : (app.wsConnected ? '在线 · 实时连接正常' : '在线 · 实时连接重连中') }}</small></div></div><div v-if="role === 'SALES'" class="progress"><span>本月目标完成度</span><b>{{ targetValue>0 ? `${performance.progress||0}%` : '未设目标' }}</b><em><i :style="{width: `${targetValue>0?(performance.progress||0):0}%`}"></i></em></div><div v-if="role === 'SALES'" class="kpi-grid"><Kpi label="销售额" :value="`¥${money(performance.amount)}`"/><Kpi label="成交单数" :value="performance.orders || 0"/><Kpi label="客单价" :value="`¥${money(performance.avg)}`"/><Kpi label="提成金额" :value="`¥${money(performance.commission)}`"/></div><div class="quick-row"><button v-if="role === 'SALES' && auth.can('member:follow')" class="notice-card" @click="router.push('/visits')"><b>{{ visitStats.pending }}</b><span>待回访</span><em>回访任务 ›</em></button><button v-if="auth.can('order:create')" class="notice-card" @click="section='order'"><b>＋</b><span>去开单</span><em>扫码收银 ›</em></button><button v-if="auth.can('goods:search')" class="notice-card" @click="router.push('/goods/search')"><b>🔍</b><span>货品搜寻</span><em>查库存价格 ›</em></button></div><Panel v-if="!isManager" title="常用功能"><div class="function-grid"><button v-for="item in salesFunctions" :key="item.key" v-permission="item.permission" class="function-entry" @click="openFunction(item)"><b>{{ SALES_FUNCTION_ICONS[item.key] || '▣' }}</b><span>{{ item.label }}</span></button></div></Panel><Panel v-if="role === 'SALES'" title="近期趋势"><TrendBars :values="trendValues" :labels="salesTrendLabels"/></Panel></section>
      <section v-else-if="!isManager && section === 'members'" class="page"><PageTitle :title="role === 'SALES' ? '我的会员' : '会员查询'"><button v-if="auth.can('member:create')" class="outline" @click="memberCreateOpen=true">新增会员</button><button class="outline" @click="loadMembers">刷新</button></PageTitle><button v-if="role === 'SALES' && auth.can('member:follow')" class="entry" @click="router.push('/visits')"><span class="entry-main">回访任务</span><span class="entry-sub">待回访 {{ visitStats.pending }} · 去处理 ›</span></button><div class="search"><input v-model="keyword" placeholder="搜索姓名或手机号" @keyup.enter="loadMembers"/><button @click="loadMembers">搜索</button></div><div v-if="role === 'SALES'" class="seg"><button :class="{active: memberTab==='mine'}" @click="memberTab='mine'">我的会员</button><button :class="{active: memberTab==='pool'}" @click="memberTab='pool'">公海池</button></div><MemberList :members="members" :sales="role === 'SALES' && memberTab==='mine'" @open="openMember" @claim="claim"/></section>
      <section v-else-if="auth.can('order:create') && section === 'order'" class="page"><PageTitle title="移动开单"><span class="state" :class="{disabled: app.offline}">{{ app.offline ? '离线不可开单' : '在线可提交' }}</span></PageTitle><div class="order-form"><div class="order-member"><label>客户（选填，选会员成交后自动排3天回访）<input v-model="order.memberKeyword" @input="searchOrderMember" placeholder="姓名或手机号搜索会员"/><small v-if="order.memberId" class="member-picked">已选：{{ order.memberName }} · {{ order.memberPhone }} <button class="outline" type="button" @click="clearOrderMember">更换</button></small><div v-else-if="orderMemberHits.length" class="member-hits"><button v-for="m in orderMemberHits" :key="m.member_id" type="button" @click="pickOrderMember(m)">{{ m.name }} · {{ m.phone }}</button></div></label></div><label>商品条码<input v-model="order.barcode" @keyup.enter="scanOrSearch" placeholder="扫码或输入条码"/><small class="muted">扫码或输入后按回车，自动加入下方清单</small></label><div v-for="(item,i) in order.items" :key="i" class="order-item"><img v-if="item.image" :src="item.image" class="item-thumb" @click="previewGoods(item.image)"/><div v-else class="item-thumb empty">无图</div><div class="item-info"><span class="item-name">{{ item.itemName }}</span><small class="muted">{{ item.weight ? Number(item.weight).toFixed(2) + 'g' : '按件计价' }}{{ item.goldType ? ' · ' + item.goldType : '' }} · 单价 ¥{{ money(item.unitPrice) }}</small><small :class="Number(item.availableStock) > 0 ? 'muted' : 'error'">可售 {{ Number(item.availableStock || 0) }} 件{{ Number(item.availableStock || 0) <= 0 ? ' · 已被待收款订单占用' : '' }}</small></div><div class="item-ops"><input v-model.number="item.qty" type="number" min="1" :max="Math.max(1, Number(item.availableStock || 0))" :disabled="Boolean(item.pieceNos?.length)" @change="normalizeOrderQty(item)"/><strong>¥{{ money(item.subtotal * item.qty) }}</strong><button class="del" type="button" @click="order.items.splice(i,1)">删除</button></div></div><button class="outline full" @click="scan">扫码添加商品</button><label>工费<input v-model.number="order.laborFee" type="number" min="0"/></label><label>折扣（填小数，0.85＝85折）<input v-model.number="order.discount" type="number" min="0.01" max="1" step="0.01" placeholder="0.85"/><small v-if="order.discount>1 || order.discount<=0" class="error">折扣应填 0.01~1 之间的小数，例如 0.85 表示 85折</small><small v-else-if="order.discount < threshold" class="error">低于{{ threshold*10 }}折，将提交审批</small></label><div class="old-mobile"><div class="section-label">旧金抵扣</div><div v-for="(m,i) in order.oldMetals" :key="m.id" class="old-line"><span>{{m.materialType}} · {{m.weight}}g · {{(Number(m.purity||0)*100).toFixed(1)}}%</span><b>¥{{money(m.weight*m.purity*(m.price||recyclePrice||0))}}</b><button @click="order.oldMetals.splice(i,1)">删除</button></div><div class="old-add"><select v-model="oldMetal.materialType" aria-label="旧料类型"><option value="" disabled>选择旧料类型</option><option v-for="type in oldMaterialTypes" :key="type.type_id || type.name" :value="type.name">{{ type.name }}</option></select><input v-model.number="oldMetal.weight" type="number" min="0" step="0.001" placeholder="克重"/><input v-model.number="oldMetal.purity" type="number" min="0" max="1" step="0.001" placeholder="成色"/><button class="outline" :disabled="!recyclePrice" @click="addOldMetal">添加旧金</button></div><small v-if="oldMaterialTypeError" class="error">{{ oldMaterialTypeError }}</small><small v-if="!recyclePrice" class="error">回收金价不可用，暂不能添加旧金抵扣</small><small>抵扣合计 ¥{{money(oldDeduct)}}</small></div></div><div class="checkout-bar"><div class="sum"><span>应收 · 含工费−旧金抵扣</span><b>¥{{ money(orderTotal) }}</b></div><button class="primary" :disabled="app.offline || !order.items.length" @click="startCheckout">转交前台结算</button></div><div class="bar-spacer"></div></section>
      <section v-else-if="auth.can('report:view') && section === 'performance'" class="page"><PageTitle title="个人业绩"/><div class="progress"><span>本月目标完成度</span><b>{{ targetValue>0 ? `${performance.progress||0}%` : '未设目标' }}</b><em><i :style="{width: `${targetValue>0?(performance.progress||0):0}%`}"></i></em></div><div class="kpi-grid"><Kpi label="销售额" :value="`¥${money(performance.amount)}`"/><Kpi label="成交单数" :value="performance.orders || 0"/><Kpi label="客单价" :value="`¥${money(performance.avg)}`"/><Kpi label="提成金额" :value="`¥${money(performance.commission)}`"/></div><Panel title="近期趋势"><TrendBars :values="trendValues" :labels="salesTrendLabels"/></Panel><Panel title="提成明细"><div v-for="(row,i) in commission" :key="i" class="rank-row"><span>{{ row.month || row.date }}</span><strong>¥{{ money(row.commission_amount) }}</strong><small>{{ row.description || '销售提成' }}</small></div></Panel></section>
      <section v-else-if="isManager && section === 'goods'" class="page"><PageTitle title="货品管理"><button class="outline" @click="router.push('/goods/search')">搜索货品</button></PageTitle><Panel :title="goodsTabTitle"><div class="chips"><button v-for="t in goodsTabs" :key="t.key" :class="{active: goodsTab===t.key}" @click="goodsTab=t.key">{{ t.label }}</button></div><template v-if="goodsTab==='overview'"><div class="kpi-grid"><Kpi label="库存总金额" :value="`¥${money(stockRoots.reduce((s,r)=>s+Number(r.amount||0),0))}`"/><Kpi label="库存件数" :value="stockRoots.reduce((s,r)=>s+Number(r.quantity||0),0)"/></div><div class="chips"><button :class="{active: wallCat===null}" @click="pickWallCat(null)">全部</button><button v-for="root in stockRoots" :key="root.category_id" :class="{active: wallCat===root.category_id}" @click="pickWallCat(root.category_id)">{{ root.category }} {{ root.quantity }}件</button></div><div v-if="wallLoading" class="empty">加载中…</div><div v-else-if="!wallGoods.length" class="empty">暂无在库货品</div><div v-for="g in wallGoods" :key="g.goods_id" class="goods-card"><img v-if="goodsImage(g.piece_image || g.images)" :src="goodsImage(g.piece_image || g.images)" class="item-thumb big" @click="previewGoods(goodsImage(g.piece_image || g.images))"/><div v-else class="item-thumb big empty">无图</div><div class="item-info"><span class="item-name">{{ g.name }}</span><small class="muted">{{ g.barcode || '无条码' }}{{ g.weight ? ' · ' + Number(g.weight).toFixed(2) + 'g' : '' }}{{ g.gold_type ? ' · ' + g.gold_type : '' }}{{ Number(g.status)===1 ? '' : ' · 未上架' }}</small><small class="muted">{{ g.parent_category ? g.parent_category + ' / ' + (g.category||'') : (g.category||'') }}</small></div><div class="item-ops"><strong>库存 {{ g.stock }}</strong><small>¥{{ money(g.sale_price) }}</small></div></div></template><template v-else-if="goodsTab==='warning'"><div v-for="w in warnings" :key="'gw'+w.goods_id" class="goods-card"><img v-if="goodsImage(w.piece_image || w.images)" :src="goodsImage(w.piece_image || w.images)" class="item-thumb big" @click="previewGoods(goodsImage(w.piece_image || w.images))"/><div v-else class="item-thumb big empty">无图</div><div class="item-info"><span class="item-name">{{ w.name || w.goods_name }}</span><small class="muted">{{ w.barcode || '无条码' }}{{ w.weight ? ' · ' + Number(w.weight).toFixed(2) + 'g' : '' }}{{ w.gold_type ? ' · ' + w.gold_type : '' }}</small><small class="muted">{{ w.category || '' }}</small></div><div class="item-ops"><strong class="error">剩余 {{ w.stock }}</strong><small>¥{{ money(w.sale_price) }}</small></div></div><div v-if="!warnings.length" class="empty">库存充足</div></template><template v-else-if="goodsTab==='old'"><div v-for="m in oldMaterials.slice(0,8)" :key="'om'+m.material_type" class="rank-row"><span>{{ m.material_type }}</span><strong>{{ m.total_weight||0 }}g</strong><small>¥{{ money(m.total_value) }} · {{ m.inbound_count||0 }}笔</small></div><div v-if="!oldMaterials.length" class="empty">暂无旧料</div></template><template v-else><div v-for="c in stockChecks.slice(0,6)" :key="'ck'+c.check_id" class="rank-row"><span>{{ c.bill_no }}</span><b :class="c.status===3?'ok':(c.status===4?'error':'')">{{ c.status===3?'已通过':(c.status===4?'已驳回':'待处理') }}</b><small>{{ (c.create_time||'').slice(0,10) }}</small></div><div v-if="!stockChecks.length" class="empty">暂无盘点记录</div></template></Panel></section>
      <section v-else-if="role === 'SALES' && section === 'goods'" class="page"><PageTitle title="货品"/><button class="outline full" @click="router.push('/goods/search')">🔍 搜索货品（条码/名称）</button><p class="muted small">支持扫码或手动输入条码查询商品信息与价格</p></section>
      <section v-else-if="section === 'notifications'" class="page"><PageTitle title="消息通知"><button class="outline" @click="loadNotifications">刷新</button></PageTitle><article v-for="notice in notices" :key="notice.id" class="list-card" :class="{unread: !notice.read}" @click="markNotificationRead(notice)"><div><b>{{ notice.title }}</b><p>{{ notice.text }}</p><small>{{ notice.time }}</small></div><span>{{ notice.read ? '已读' : '未读' }}</span></article><div v-if="!notices.length" class="empty">暂无消息</div></section>
      <section v-else-if="section === 'profile'" class="page"><ProfilePanel @go="k=>section=k"/></section>
      <section v-else-if="isManager && section === 'kpidetail'" class="page"><PageTitle :title="kpiDetailTitle"><button class="outline" @click="section='dashboard'">返回看板</button></PageTitle><p class="muted small" style="margin:0 0 10px">{{ kpiDetailSummary }}</p><Panel :title="kpiDetailTitle"><div v-if="kpiDetailLoading" class="empty">加载中...</div><template v-else><div v-for="(row,i) in kpiDetailRows" :key="i" class="rank-row"><span>{{ row.title }}<small>{{ row.sub }}</small></span><strong>{{ row.amount }}</strong><small>{{ row.extra }}</small></div><div v-if="!kpiDetailRows.length" class="empty">今日暂无明细</div></template></Panel></section>
      <section v-else-if="isManager && section === 'trend'" class="page"><PageTitle title="7日营业额趋势"><button class="outline" @click="section='dashboard'">返回看板</button></PageTitle><Panel title="每日营业额"><TrendBars :values="managerTrendValues" :labels="managerTrendLabels"/><div class="trend-detail-list"><div v-for="row in managerTrendRows" :key="row.day" class="rank-row"><span>{{ formatDay(row.day) }}</span><strong>¥{{ money(row.amount) }}</strong><small>{{ row.orderCount }} 单 · 已结算</small></div><div v-if="!managerTrendRows.length" class="empty">暂无趋势数据</div></div></Panel><p class="muted small">数据与管理端仪表盘共用 /api/admin/dashboard，订单完成后自动刷新。</p></section>
