orm.gender"><option value="">未填写</option><option value="女">女</option><option value="男">男</option></select></label><label class="form-label">生日<input v-model="memberForm.birthday" type="date"/></label><div class="action-row"><button class="outline" @click="memberCreateOpen=false">取消</button><button class="primary" :disabled="memberCreating" @click="submitMemberCreate">{{ memberCreating?'保存中...':'保存' }}</button></div></div></div>
