const route=useRoute(); const router=useRouter(); const auth=useAuthStore(); const app=useAppStore(); const role=computed(()=>auth.role); const isManager=computed(()=>role.value==='MANAGER'||role.value==='ADMIN'); const canInbound=computed(()=>auth.can('stock:inbound:create')); const section=ref(sectionForRole(route.params.section || (isManager.value?'dashboard':'home'), role.value)); const today=new Date().toLocaleDateString('zh-CN'); const dashboard=ref({}); const warnings=ref([]); const ranking=ref([]); const approvals=ref([]); const approvalFilter=ref('全部'); const approvalTabs=['全部','价格审批','退货审批','回收审批','盘点审批']; const report=ref({}); const period=ref('daily'); const commission=ref([]); const members=ref([]); const keyword=ref(''); const memberTab=ref('mine'); const visits=ref([]); const threshold=ref(0.85); const performance=ref({}); const trendValues=ref([]); const oldMaterialTypes=ref([]); const oldMaterialTypeError=ref(''); const oldMetal=reactive({weight:0,purity:.999,materialType:''}); const order=ref({memberId:null,memberName:'',memberPhone:'',memberKeyword:'',barcode:'',items:[],laborFee:0,discount:1,oldMetals:[]}); const orderMemberHits=ref([]); let orderMemberTimer=null; const touchStartPoint=ref({x:0,y:0}); const touchMoved=ref(false); let suppressPanelClickUntil=0; const memberPage=ref(1); const goldHistory=ref([]); const tierMembers=ref([]); const reportError=ref(''); const categoryProfit=ref([]); const spotPrice=ref(0)
