const salesTrendLabels=[...Array(7)].map((_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));return i===6?'今天':WEEKDAYS[d.getDay()]})
const dayKey=(d)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`
function alignTrend(rows){const byDay=new Map((Array.isArray(rows)?rows:[]).map(r=>[String(r.day||r.date||'').slice(0,10),Number(r.amount||r.revenue||0)]));const vals=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);vals.push(byDay.get(dayKey(d))||0)}return vals}
const recyclePrice=computed(()=>{const rows=Array.isArray(app.gold)?app.gold:[];const hit=rows.find(x=>String(x.price_type||x.priceType||'').includes('回收'));const price=Number(hit&&hit.price);return price>0?price:null})
const TAB_ICONS={dashboard:'⌂',report:'♙',member:'👤',members:'👥',order:'＋',performance:'↗',notifications:'●',profile:'⚙'}
const tabs=computed(()=>tabsForRole(role.value,auth.permissions).map(tab=>({...tab,icon:TAB_ICONS[tab.key]||'•'})))
const pageTitle=computed(()=>({dashboard:'首页',kpidetail:'数据明细',report:'业绩报表',member:'会员总览',goods:'货品管理',approval:'审批中心',trend:'7日营业额趋势',home:'首页',members:role.value==='SALES'?'我的会员':'会员查询',order:'移动开单',performance:'个人业绩',notifications:'消息通知',profile:'我的'}[section.value]||'打金店'))
const typeName=(t)=>TYPE_NAMES[String(t||'').toUpperCase()]||t||'业务审批'
const visitStats=computed(()=>{const p=visits.value.filter(t=>Number(t.status??1)===1).length;const d=visits.value.filter(t=>Number(t.status??1)===2).length;const total=p+d;return {pending:p,done:d,rate:total?Math.round(d/total*100):0}})
const payMethodRows=computed(()=>(Array.isArray(paySummaryData.value)?paySummaryData.value:[]).map(r=>({category:r.pay_method||'未指定',revenue:Number(r.amount||0)})))
const filteredApprovals=computed(()=>approvalFilter.value==='全部'?approvals.value:approvals.value.filter(x=>typeName(x.type).includes(approvalFilter.value))); const oldDeduct=computed(()=>order.value.oldMetals.reduce((s,m)=>s+Number(m.weight||0)*Number(m.purity||0)*Number(m.price||recyclePrice.value||0),0)); const orderTotal=computed(()=>Math.max(0,order.value.items.reduce((s,i)=>s+(Number(i.subtotal)||0)*(Number(i.qty)||1),0)*Number(order.value.discount||1)+Number(order.value.laborFee||0)-oldDeduct.value)); const memberStats=computed(()=>{const s=memberReport.value;const fallback={total:members.value.length,new:members.value.filter(m=>String(m.create_time||'').startsWith(today)).length,active:members.value.filter(m=>m.total_consume>0).length,balance:members.value.reduce((sum,m)=>sum+Number(m.balance||0),0)};if(!s)return fallback;return {total:Number(s.total_members??fallback.total),new:Number(s.new_members??fallback.new),active:Number(s.active_members??fallback.active),balance:Number(s.balance_total??fallback.balance)}})
const money=(v)=>Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}); const round2=(v)=>Math.round((Number(v)||0)*100)/100
const categoryRows=computed(()=>{const rows=Array.isArray(categoryProfit.value)?categoryProfit.value:[];return rows.filter(r=>Number(r.revenue||0)>0).sort((a,b)=>Number(b.revenue||0)-Number(a.revenue||0)).slice(0,6)})
const goldTrendRows=computed(()=>{const rows=Array.isArray(goldHistory.value)?goldHistory.value:[];const typeName=String(app.primaryGold?.price_type||app.primaryGold?.name||'');let pick=typeName?rows.filter(r=>String(r.price_type)===typeName):[];if(!pick.length)pick=rows;const byDay=new Map();for(const r of pick){const d=String(r.date||'').slice(0,10);if(d&&r.price!=null)byDay.set(d,Number(r.price))}return [...byDay.entries()].sort((a,b)=>a[0]<b[0]?-1:1).map(([date,price])=>({date,price}))})
const tiers=computed(()=>{const list=tierMembers.value;const def=[{label:'钻石会员 ≥5万',color:'#b7791f',min:50000},{label:'高价值 ≥1万',color:'#d69e2e',min:10000},{label:'普通会员 ≥1千',color:'#4299e1',min:1000},{label:'待激活 <1千',color:'#a0aec0',min:0}];return def.map((d,i)=>{const upper=i===0?Infinity:def[i-1].min;const rows=list.filter(m=>{const c=Number(m.total_consume||0);return c>=d.min&&c<upper});return {label:d.label,color:d.color,count:rows.length,amount:rows.reduce((s,m)=>s+Number(m.total_consume||0),0)}})})
async function loadMembers(reset=true){if(reset)memberPage.value=1;try{const fetcher=memberTab.value==='pool'?api.memberPool:api.members;const d=await fetcher({keyword:keyword.value,page:memberPage.value});const rows=d.records||d||[];members.value=reset?rows:[...members.value,...rows];setStorage('dajin-members',JSON.stringify(members.value))}catch{try{members.value=JSON.parse(getStorage('dajin-members','[]'))}catch{members.value=[]}}} async function loadMore(){memberPage.value++;await loadMembers(false)} async function loadManager(){try{const d=await api.dashboard()||{};dashboard.value={...d,amount:d.amount??d.revenue,order_count:d.order_count??d.orderCount,avg_order:d.avg_order??(Number(d.revenue||0)/Math.max(1,Number(d.orderCount||d.order_count||0)))};warnings.value=await api.warnings()||[];approvals.value=await api.approvals()||[];app.approvals=approvals.value;ranking.value=dashboard.value.ranking||dashboard.value.staffRanking||[]}catch{}try{categoryProfit.value=await api.categoryProfit()||[]}catch{categoryProfit.value=[]}try{goldHistory.value=await api.goldHistory(30)||[]}catch{goldHistory.value=[]}try{const s=await api.stock()||[];stockRoots.value=Array.isArray(s)?s:[]}catch{stockRoots.value=[]}try{oldMaterials.value=await api.oldMaterial()||[]}catch{oldMaterials.value=[]}try{stockChecks.value=await api.stockChecks()||[]}catch{stockChecks.value=[]}try{paySummaryData.value=await api.paySummary()||[]}catch{paySummaryData.value=[]}try{recycleData.value=await api.recycleStats()||{}}catch{recycleData.value={}}loadWall()}
async function loadReport(){reportError.value='';if(role.value==='SALES'){try{const [d,t]=await Promise.all([api.performance(),api.systemTarget().catch(()=>null)]);targetValue.value=Number(t?.monthlySalesTarget||0);report.value=d||{};commission.value=d?.employees||[];trendValues.value=alignTrend(d?.trend||[]);performance.value={amount:d?.amount||0,orders:d?.order_count||0,avg:d?.avg_order||0,commission:d?.commission||0,progress:targetValue.value>0?Math.round(Number(d?.amount||0)/targetValue.value*100):0};return}catch(error){reportError.value=error?.message||'个人业绩加载失败';report.value={};commission.value=[];performance.value={};return}}try{const d=await api.reports(period.value);if(period.value!=='daily'&&Array.isArray(d)){const rows=d;report.value={amount:rows.reduce((s,r)=>s+Number(r.amount||0),0),order_count:rows.reduce((s,r)=>s+Number(r.order_count||0),0)};trendValues.value=rows.map(r=>Number(r.amount||0))}else{report.value=d||{};if(Array.isArray(report.value.trend))trendValues.value=report.value.trend.map(x=>Number(x.amount||x.value||0))}}catch(error){report.value={};reportError.value=error?.message||'报表加载失败，请重试'}try{const d=await api.performance();commission.value=d?.employees||[]}catch{commission.value=[]}try{const t=await api.systemTarget();targetValue.value=Number(t?.monthlySalesTarget||0)}catch{}}
async function loadMemberReport(){try{const d=await api.reportMember({timeType:'month'});memberReport.value=d?.summary||d||null}catch{memberReport.value=null}}
async function submitMemberCreate(){if(!memberForm.name.trim())return alert('请填写会员姓名');if(!/^1[3-9]\d{9}$/.test(memberForm.phone))return alert('请填写正确的11位手机号');memberCreating.value=true;try{await api.memberCreate({name:memberForm.name.trim(),phone:memberForm.phone,gender:memberForm.gender||null,birthday:memberForm.birthday||null});memberCreateOpen.value=false;memberForm.name='';memberForm.phone='';memberForm.gender='';memberForm.birthday='';alert('会员已创建');loadMembers();loadMemberReport()}catch(e){alert(e?.message||'会员创建失败')}finally{memberCreating.value=false}}
async function loadTiers(){if(tierMembers.value.length)return;try{const all=[];for(let p=1;p<=5;p++){const d=await api.members({page:p,size:100});const rows=d.records||d||[];all.push(...rows);if(rows.length<100)break}tierMembers.value=all}catch{tierMembers.value=[]}}
const approvalConfirming=ref(false)
function closeApprovalDetail(){approvalDetail.value=null;approvalConfirming.value=false}
async function openApprovalHistory(){approvalView.value='history';try{approvalHistoryData.value=await api.approvalHistory()||[]}catch{approvalHistoryData.value=[]}}
async function openApprovalDetail(item,forReject){approvalConfirming.value=false;const id=item.approval_id||item.id;try{const d=await api.approvalDetail(id);approvalDetail.value=d;approvalItems.value=[];approvalRemark.value='';const items=d.approval?.items||d.orderItems||d.items||[];approvalItems.value=items;if(forReject)approvalRemark.value=''}catch(e){alert(e.message)}}
async function decideApproval(status){const id=approvalDetail.value?.approval?.approval_id||approvalDetail.value?.approval?.id;if(!id)return;if(status===3&&!approvalConfirming.value){approvalConfirming.value=true;return}approvalConfirming.value=false;try{if(status===3){const excess=Number(approvalDetail.value?.order?.old_material_excess||0);const confirmation={};if(approvalDetail.value?.approval?.type==='REFUND'&&excess>0){if(!window.confirm(`确认已按原渠道收回返款 ${money(excess)}，并核对退还旧料？`))return;confirmation.oldMaterialExcessRecovered=true}await api.approve(id,approvalRemark.value,confirmation)}else{if(!approvalRemark.value){alert('驳回必须填写原因');return}await api.reject(id,approvalRemark.value)}approvals.value=approvals.value.filter(x=>(x.approval_id||x.id)!==id);approvalDetail.value=null;if(approvalView.value==='history')openApprovalHistory()}catch(e){alert(e.message)}}
async function loadBirthdayMembers(){try{const d=await api.members({birthdayFilter:'month',size:50});const rows=d.records||d||[];birthdayMembers.value=rows}catch{birthdayMembers.value=[]}} async function loadOldMaterialTypes(){oldMaterialTypeError.value='';try{const rows=await api.oldMaterialTypes();const list=(Array.isArray(rows)?rows:rows?.records||[]).filter(row=>Number(row.status ?? 1)===1 && String(row.name||'').trim());oldMaterialTypes.value=list;if(!oldMetal.materialType && list.length)oldMetal.materialType=list[0].name;if(!list.length)oldMaterialTypeError.value='暂无启用的旧料类型，请先在管理端配置'}catch(error){oldMaterialTypes.value=[];oldMaterialTypeError.value=error?.message||'旧料类型加载失败，请检查网络连接'} } function openMember(m){router.push(`/member/${m.member_id||m.id}`)} function claim(m){api.claimMember(m.member_id||m.id).then(()=>loadMembers()).catch(e=>alert(e.message||'认领失败'))} function call(phone){if(typeof uni!=='undefined')uni.makePhoneCall({phoneNumber:phone});else window.location.href=`tel:${phone}`}
let orderScanBusy=false
async function scan(){
  if(orderScanBusy)return
  orderScanBusy=true
  try{
    let code=''
    if(typeof uni!=='undefined'&&typeof uni.scanCode==='function'){
      code=await new Promise((resolve,reject)=>uni.scanCode({scanType:['qrCode','barCode'],success:r=>resolve(r.result),fail:e=>reject(new Error(String(e?.errMsg||'').includes('cancel')?'已取消扫码':'扫码失败，请重试'))}))
    }else code=await scanBarcodeFromCamera()
    code=String(code||'').trim()
    if(!code)return
    order.value.barcode=code
    await scanOrSearch()
  }catch(error){
    const message=error?.message||'扫码失败，请重试'
    if(!message.includes('取消'))alert(`${message}，也可以在上方手动输入条码`)
  }finally{orderScanBusy=false}
}
function goodsImage(v){if(typeof v==='string'&&/^(https?:|\/(?!\/))/.test(v.trim())){const u=v.trim();return u.startsWith('/')?http.defaults.baseURL+u:u}let l=v;if(typeof l==='string'){try{l=JSON.parse(l||'[]')}catch{l=[]}}const list=Array.isArray(l)?l.filter(Boolean):[];const u=list[0]?String(list[0]):'';return u.startsWith('/')?http.defaults.baseURL+u:u}
function previewGoods(u){if(u)window.open(u)}
const wallCat=ref(null);const wallGoods=ref([]);const wallLoading=ref(false)
async function loadWall(){wallLoading.value=true;try{const d=await api.goods({parentCategoryId:wallCat.value||undefined,size:100,includeInactive:true});wallGoods.value=(d.records||d||[]).filter(g=>Number(g.stock)>0)}catch{wallGoods.value=[]}finally{wallLoading.value=false}}
function pickWallCat(id){wallCat.value=id;loadWall()}
async function scanOrSearch(){
  const parsed=parseInboundScanPayload(order.value.barcode);if(!parsed.barcode&&!parsed.pieceNo)return
  try{
    let g
    if(parsed.pieceNo){
      if(order.value.items.some(item=>(item.pieceNos||[]).includes(parsed.pieceNo)))return alert('该单件码已在购物清单中')
      g=await api.goodsByPieceNo(parsed.pieceNo)
    }else{
      const d=await api.goods({keyword:parsed.barcode});g=(d.records||d||[]).find(row=>String(row.barcode)===String(parsed.barcode))
    }
    if(!g)return alert('未找到该商品')
    const availableStock=Math.max(0,Math.floor(Number(g.available_stock ?? g.stock ?? 0)))
    if(availableStock<=0)return alert('该商品已售罄或已被待收款订单占用')
    const gramPriced=Number(g.price_type)===1
    if(gramPriced&&!(Number(app.primaryGold?.price)>0))return alert('今日金价未获取到，暂不能按克计价，请刷新后重试')
    const unitPrice=gramPriced?Number(g.weight||0)*Number(app.primaryGold?.price):Number(g.sale_price||0)
    const exist=order.value.items.find(x=>Number(x.goodsId)===Number(g.goods_id)&&Boolean((x.pieceNos||[]).length)===Boolean(parsed.pieceNo))
    if(exist){
      exist.availableStock=availableStock
      const nextQty=(Number(exist.qty)||0)+1
      if(nextQty>availableStock)return alert(`可售库存仅剩 ${availableStock} 件，不能继续添加`)
      if(parsed.pieceNo){exist.pieceNos.push(parsed.pieceNo);exist.qty=exist.pieceNos.length}else exist.qty=nextQty
    }else order.value.items.push({goodsId:g.goods_id,barcode:g.barcode||parsed.barcode,itemName:g.goods_name||g.name,qty:1,availableStock,pieceNos:parsed.pieceNo?[parsed.pieceNo]:[],subtotal:unitPrice,weight:g.weight,unitPrice,goldType:g.gold_type,image:goodsImage(g.piece_image||g.images)})
    order.value.barcode=''
  }catch(error){alert(error?.message||'商品查询失败')}
}
function normalizeOrderQty(item,silent=false){
  if(Array.isArray(item.pieceNos)&&item.pieceNos.length){item.qty=item.pieceNos.length;return}
  const available=Math.max(0,Math.floor(Number(item.availableStock||0)))
  const requested=Math.max(1,Math.floor(Number(item.qty)||1))
  item.qty=available>0?Math.min(requested,available):1
  if(!silent&&available<=0)alert('该商品已被待收款订单占用，请删除后重新选择')
  else if(!silent&&requested>available)alert(`可售库存仅剩 ${available} 件`)
}
async function refreshOrderAvailability(){
  await Promise.all(order.value.items.map(async item=>{
    try{
      if(Array.isArray(item.pieceNos)&&item.pieceNos.length){
        const rows=await Promise.all(item.pieceNos.map(pieceNo=>api.goodsByPieceNo(pieceNo)))
        item.availableStock=Math.max(0,Math.floor(Number(rows[0]?.available_stock ?? rows[0]?.stock ?? item.pieceNos.length)))
      }else if(item.barcode){
        const d=await api.goods({keyword:item.barcode,size:20});const rows=d.records||d||[]
        const current=rows.find(row=>Number(row.goods_id)===Number(item.goodsId))
        item.availableStock=current?Math.max(0,Math.floor(Number(current.available_stock ?? current.stock ?? 0))):0
      }
    }catch{item.availableStock=0}
    normalizeOrderQty(item,true)
  }))
}
function addOldMetal(){if(!recyclePrice.value)return alert('回收金价暂不可用，无法计算旧金抵扣，请刷新金价后重试');if(!oldMetal.materialType)return alert('请选择旧料类型');if(oldMetal.weight<=0||oldMetal.purity<=0)return alert('请输入有效的克重和成色');order.value.oldMetals.push({id:Date.now(),materialType:oldMetal.materialType,weight:Number(oldMetal.weight),purity:Number(oldMetal.purity),price:recyclePrice.value});oldMetal.weight=0}
function searchOrderMember(){clearTimeout(orderMemberTimer);const kw=String(order.value.memberKeyword||'').trim();if(!kw){orderMemberHits.value=[];return}orderMemberTimer=setTimeout(async()=>{try{const d=await api.members({keyword:kw,size:5});orderMemberHits.value=d.records||d||[]}catch{orderMemberHits.value=[]}},300)}
function pickOrderMember(m){order.value.memberId=m.member_id;order.value.memberName=m.name;order.value.memberPhone=m.phone;orderMemberHits.value=[]}
function clearOrderMember(){order.value.memberId=null;order.value.memberName='';order.value.memberPhone='';order.value.memberKeyword='';orderMemberHits.value=[]}
async function loadNotifications(){try{const rows=await api.notifications()||[];notices.value=rows.map(row=>{const rawTitle=String(row.title||'').trim();const action=String(row.action||'').toUpperCase();return{id:row.notification_id||row.log_id,title:rawTitle&&rawTitle.toUpperCase()!=='READ'?rawTitle:({REMIND:'超期/库存提醒',PROCESSING_READY:'加工完成提醒',PROCESSING_LOSS_OVER:'损耗超标预警',APPROVAL_CREATED:'审批提醒',REMINDER_REFRESH:'提醒'}[action]||'通知'),text:row.text||row.content||'消息通知',time:row.time||row.create_time||'',read:row.read===true||action==='READ'}})}catch{notices.value=[]}}
async function markNotificationRead(notice){if(notice.read)return;notice.read=true;try{await api.markNotificationRead(notice.id)}catch{}}
  function orderPayload(){return {memberId:order.value.memberId||null,discount:order.value.discount||1,oldMaterialDeduct:round2(oldDeduct.value),laborFee:round2(order.value.laborFee||0),payAmount:round2(orderTotal.value),payMethod:'PENDING',salesId:auth.user?.user_id,remark:order.value.memberId?null:(order.value.memberKeyword?`客户:${order.value.memberKeyword}`:null),items:order.value.items.map(i=>{const pieceNos=Array.isArray(i.pieceNos)?i.pieceNos:[];const qty=pieceNos.length||i.qty||1;return {goodsId:i.goodsId,itemName:i.itemName,weight:Number(i.weight)>0?i.weight:null,unitPrice:round2(i.unitPrice||i.subtotal),laborFee:0,qty,pieceNos,subtotal:round2((i.subtotal||0)*qty)}}),oldMaterials:order.value.oldMetals.map(m=>({materialType:m.materialType||'旧金抵扣',weight:m.weight,purity:m.purity,priceType:'回收金价',price:m.price})),clientRequestId:`mobile-${Date.now()}`,version:1}} function resetCart(){order.value.items=[];order.value.oldMetals=[];clearOrderMember()}
async function startCheckout(){if(!(Number(order.value.discount)>0&&Number(order.value.discount)<=1))return alert('折扣应填 0.01~1 之间的小数，例如 0.85 表示 85折');if(!order.value.items.length)return alert('请先扫码或输入条码添加商品，再转交');const unavailable=order.value.items.find(item=>Number(item.qty||0)>Number(item.availableStock||0));if(unavailable)return alert(`${unavailable.itemName} 可售库存不足，请删除后重新扫码`);try{const d=await api.createOrder({ ...orderPayload(), handover:true });if(d.approvalRequired){alert('折扣低于阈值，已提交店长审批，审批通过后前台可收款');resetCart();return}resetCart();alert(`订单 ${d.orderNo || ''} 已转交前台，请在收银端「前台待办」完成收款`)}catch(e){alert(e.message)}}
function touchStart(e){const point=e.changedTouches?.[0];touchStartPoint.value={x:point?.screenX||0,y:point?.screenY||0};touchMoved.value=false}
function touchMove(e){const point=e.changedTouches?.[0];if(!point)return;touchMoved.value ||= Math.abs(point.screenX-touchStartPoint.value.x)>8 || Math.abs(point.screenY-touchStartPoint.value.y)>8}
function touchEnd(){if(touchMoved.value)suppressPanelClickUntil=Date.now()+350;touchMoved.value=false}
function handleOnline(){app.setOffline(false);app.checkConnectivity()} function handleOffline(){app.setOffline(true)}
onMounted(()=>{window.addEventListener('online',handleOnline);window.addEventListener('offline',handleOffline);app.refreshLocalPendingInbounds();if(isManager.value){loadManager();loadReport();loadMembers();loadSpotPrice()}else{if(auth.can('member:view'))loadMembers();if(role.value==='SALES'&&auth.can('report:view'))loadReport()}loadOldMaterialTypes();app.loadGold()})
onBeforeUnmount(()=>{window.removeEventListener('online',handleOnline);window.removeEventListener('offline',handleOffline)})
onMounted(()=>{if(!isManager.value)loadVisits()})
async function loadVisits(){try{visits.value=await api.visits()||[]}catch{visits.value=[]}}
watch(()=>app.eventVersion,()=>{
  if(app.lastEventType==='MEMBER_UPDATED'){
    if(auth.can('member:view'))loadMembers()
    loadMemberReport()
    if(isManager.value){tierMembers.value=[];loadTiers();loadBirthdayMembers()}
    return
  }
  if(app.lastEventType==='VISIT_TASK_UPDATED'){loadVisits();return}
  if(app.lastEventType==='STOCK_UPDATED'){if(section.value==='order'&&order.value.items.length)refreshOrderAvailability();if(isManager.value)loadManager();return}
  if(['REPORT_UPDATED','COMMISSION_UPDATED','TARGET_UPDATED'].includes(app.lastEventType)){loadReport();if(isManager.value)loadManager();return}
  if(isManager.value)loadManager();else if(auth.can('report:view'))loadReport()
})
watch(()=>order.value.items,items=>{for(const item of items){if(Array.isArray(item.pieceNos)&&item.pieceNos.length)item.qty=item.pieceNos.length}},{deep:true})
watch(memberTab,()=>loadMembers())
watch(section,(v)=>{const normalized=sectionForRole(v,role.value);if(normalized!==v){section.value=normalized;return}if(v==='visits'){router.push('/visits');return}if(canInbound.value&&v==='inbound'){router.push('/inbound/create');return}if((v==='report'||v==='performance')&&auth.can('report:view')){router.replace('/report');return}if(isManager.value&&v==='member'){loadTiers();loadBirthdayMembers();loadMemberReport()}if(v==='notifications')loadNotifications();if(v==='members')loadMembers()},{immediate:true})
const managerTrendRows=computed(()=>{const rows=Array.isArray(dashboard.value?.trend)?dashboard.value.trend:[];return rows.map(row=>({day:String(row.day||row.date||'').slice(0,10),amount:Number(row.amount||row.revenue||0),orderCount:Number(row.order_count||row.orderCount||0)})).filter(row=>row.day)})
const managerTrendValues=computed(()=>managerTrendRows.value.map(row=>row.amount))
const managerTrendLabels=computed(()=>managerTrendRows.value.map(row=>row.day))
function weekdayLabel(day){const d=new Date(String(day));return Number.isNaN(d.getTime())?String(day).slice(5):WEEKDAYS[d.getDay()]}
const managerTrendWeekdayLabels=computed(()=>managerTrendRows.value.map((row,i)=>i===managerTrendRows.value.length-1?'今天':weekdayLabel(row.day)))
function formatDay(value){const text=String(value||'');return text.length>=10?text.slice(5):text||'-'}
function openFunction(item){if(item.section)section.value=sectionForRole(item.section,role.value);else if(item.path)router.push(item.path)}
const kpiDetailType=ref('orders'); const kpiDetailRows=ref([]); const kpiDetailSummary=ref(''); const kpiDetailLoading=ref(false)
const kpiDetailTitle=computed(()=>({orders:'今日订单明细',weight:'今日销售克重明细',avg:'今日订单明细',recycle:'今日回收明细'}[kpiDetailType.value]||'数据明细'))
function openKpiDetail(type){kpiDetailType.value=type;section.value='kpidetail';loadKpiDetail()}
async function loadKpiDetail(){kpiDetailLoading.value=true;try{if(kpiDetailType.value==='recycle'){const d=await api.reportRecycle({timeType:'today'})||{};kpiDetailSummary.value=`今日回收 ${Number(d.order_count||0)} 单 · ${Number(d.weight||0).toFixed(3)}g · ${money(d.amount)}`;kpiDetailRows.value=(d.records||[]).slice(0,50).map(r=>({title:r.material_type||'旧料回收',sub:`${r.bill_no||''} · ${String(r.create_time||'').slice(5,16).replace('T',' ')}`,amount:money(r.total_amount),extra:`${Number(r.weight||0).toFixed(3)}g · 成色 ${(Number(r.purity||0)*100).toFixed(1)}%`}));}else{const d=await api.reportOverview({timeType:'today'})||{};const s=d.summary||{};kpiDetailSummary.value=`今日 ${Number(s.order_count||0)} 单 · 营业额 ${money(s.sales_amount)} · 客单价 ${money(s.avg_order ?? (Number(s.sales_amount||0)/Math.max(1,Number(s.order_count||1))))}`;kpiDetailRows.value=(d.records||[]).slice(0,50).map(r=>({title:r.goods_name||'订单',sub:`${r.order_no||''} · ${String(r.date||'').slice(5,16)}`,amount:money(r.amount),extra:`${Number(r.weight||0).toFixed(2)}g · ${r.category||''}`}));}}catch(e){kpiDetailRows.value=[];kpiDetailSummary.value=e?.message||'明细加载失败'}finally{kpiDetailLoading.value=false}}
function handlePanelDrilldown(event){if(touchMoved.value||Date.now()<suppressPanelClickUntil)return;const panel=event.target?.closest?.('.panel');if(!panel||!isManager.value)return;const title=panel.querySelector('.panel-head h2')?.textContent?.trim()||'';if(title==='员工排行榜')section.value='report';else if(title==='7日营业额趋势')section.value='trend'}
watch(()=>dashboard.value?.trend,(rows)=>{if(Array.isArray(rows)&&rows.length)trendValues.value=alignTrend(rows)},{deep:true})
</script>
